<?php
require 'config.php';require_login();$page_title='Reports & analytics';$summary=$pdo->query("SELECT COUNT(*) total,COALESCE(SUM(status='Active'),0) active,COALESCE(SUM(status='On Leave'),0) leave_count,COALESCE(SUM(status='Resigned'),0) resigned,COALESCE(AVG(salary),0) avg_salary,COALESCE(MIN(salary),0) min_salary,COALESCE(MAX(salary),0) max_salary,COALESCE(SUM(salary),0) payroll FROM employees")->fetch();$depts=$pdo->query("SELECT d.department_name,COUNT(e.employee_id) headcount,COALESCE(AVG(e.salary),0) avg_salary,COALESCE(SUM(e.salary),0) payroll FROM departments d LEFT JOIN employees e ON e.department_id=d.department_id GROUP BY d.department_id,d.department_name ORDER BY headcount DESC")->fetchAll();$hires=$pdo->query("SELECT YEAR(hire_date) hire_year,COUNT(*) total FROM employees GROUP BY YEAR(hire_date) ORDER BY hire_year DESC")->fetchAll();include 'includes/header.php';?>
<section class="hero"><div><p class="eyebrow">WORKFORCE INSIGHTS</p><h1>Reports & analytics</h1><p class="muted">Quick summaries for staffing, status, salary, and hiring history.</p></div><button class="btn outline" onclick="window.print()">Print report</button></section>
<div class="stats"><article class="stat"><div class="stat-top">Total employees</div><strong><?=$summary['total']?></strong></article><article class="stat"><div class="stat-top">Active employees</div><strong><?=$summary['active']?></strong></article><article class="stat"><div class="stat-top">On leave</div><strong><?=$summary['leave_count']?></strong></article><article class="stat"><div class="stat-top">Resigned employees</div><strong><?=$summary['resigned']?></strong></article></div>
<?php if(is_admin()): ?><div class="report-grid"><section class="panel"><div class="panel-head"><h2>Salary overview</h2><span class="muted">Monthly · PHP</span></div><div class="metric"><span>Total monthly payroll</span><strong>₱<?=number_format((float)$summary['payroll'],2)?></strong></div><div class="metric" style="margin-top:10px"><span>Average salary</span><strong>₱<?=number_format((float)$summary['avg_salary'],2)?></strong></div><div class="metric" style="margin-top:10px"><span>Salary range</span><strong style="font-size:18px">₱<?=number_format((float)$summary['min_salary'],2)?> – ₱<?=number_format((float)$summary['max_salary'],2)?></strong></div></section><?php endif; ?><section class="panel"><div class="panel-head"><h2>Hiring by year</h2></div><?php if(!$hires): ?><p class="muted">No hiring data available.</p><?php else: ?><div class="chart-bars"><?php $maxHire=max(1,...array_column($hires,'total'));foreach($hires as $h): ?><div class="bar-row"><span><?=$h['hire_year']?></span><div class="bar-track"><div class="bar-fill" style="width:<?=round($h['total']/$maxHire*100)?>%"></div></div><b><?=$h['total']?></b></div><?php endforeach; ?></div><?php endif; ?></section></div>
<section class="panel"><div class="panel-head"><h2>Department analysis</h2></div><div class="table-wrap"><table><thead><tr><th>Department</th><th>Headcount</th><?php if(is_admin()): ?><th>Average salary</th><th>Total monthly payroll</th><?php endif; ?></tr></thead><tbody><?php foreach($depts as $d): ?><tr><td><b><?=e($d['department_name'])?></b></td><td><?=$d['headcount']?></td><?php if(is_admin()): ?><td>₱<?=number_format((float)$d['avg_salary'],2)?></td><td>₱<?=number_format((float)$d['payroll'],2)?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php if(!is_admin()): ?><p class="muted" style="font-size:12px">Salary figures are hidden for non-administrator accounts.</p><?php endif; ?></section><?php include 'includes/footer.php'; ?>